#include <iostream>
#include <cstring>
#include <queue>
#include <vector>
#include <algorithm>
using namespace std;

const int INF = 1 << 29;
const int MAXN = 500;
const int MAXQ = 1000000;

struct Edge { int a, b, cap, flow; };
vector<int> g[MAXN];
vector<Edge> e;
int d[MAXN], ptr[MAXN];
int n, t, sx, sy;
vector<int> tmp;
vector<char> passable;

void add_edge(int a, int b, int cap) {
    Edge e1 = {a, b, cap, 0};
    Edge e2 = {b, a, 0, 0};
    g[a].push_back((int)e.size());
    e.push_back(e1);
    g[b].push_back((int)e.size());
    e.push_back(e2);
}

bool bfs() {
    queue<int> q;
    q.push(0);
    memset(d, -1, (n * n * 2 + 2) * sizeof(d[0]));
    d[0] = 0;
    while (!q.empty() && d[n * n * 2 + 1] == -1) {
        int v = q.front();
        q.pop();
        for (size_t i = 0; i < g[v].size(); ++i) {
            int id = g[v][i], to = e[id].b;
            if (d[to] == -1 && e[id].flow < e[id].cap) {
                q.push(to);
                d[to] = d[v] + 1;
            }
        }
    }
    return d[n * n * 2 + 1] != -1;
}

int dfs(int v, int flow) {
    if (!flow) return 0;
    if (v == n * n * 2 + 1) return flow;
    for (; ptr[v] < (int)g[v].size(); ++ptr[v]) {
        int id = g[v][ptr[v]], to = e[id].b;
        if (d[to] != d[v] + 1) continue;
        int pushed = dfs(to, min(flow, e[id].cap - e[id].flow));
        if (pushed) {
            e[id].flow += pushed;
            e[id ^ 1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int max_flow() {
    int flow = 0;
    while (bfs()) {
        memset(ptr, 0, (n * n * 2 + 2) * sizeof(ptr[0]));
        while (int pushed = dfs(0, INF))
            flow += pushed;
    }
    return flow;
}

inline int id(int x, int y) { return x * n + y; }

int way(int x1, int y1, int x2, int y2) {
    static int qx[MAXQ], qy[MAXQ], qd[MAXQ];
    int head = 0, tail = 0;
    vector<int> h(n * n, INF);

    qx[tail] = x1;
    qy[tail] = y1;
    qd[tail++] = 0;

    while (head < tail) {
        int x = qx[head], y = qy[head], v = qd[head++];
        h[id(x, y)] = v;

        if (x > 0 && passable[id(x - 1, y)] && h[id(x - 1, y)] > v + 1) {
            bool target = (x - 1 == x2 && y == y2);
            int lim = tmp[id(x - 1, y)];
            if ((target && lim >= v + 1) || (!target && lim > v + 1)) {
                qx[tail] = x - 1;
                qy[tail] = y;
                qd[tail++] = v + 1;
            }
        }
        if (y > 0 && passable[id(x, y - 1)] && h[id(x, y - 1)] > v + 1) {
            bool target = (x == x2 && y - 1 == y2);
            int lim = tmp[id(x, y - 1)];
            if ((target && lim >= v + 1) || (!target && lim > v + 1)) {
                qx[tail] = x;
                qy[tail] = y - 1;
                qd[tail++] = v + 1;
            }
        }
        if (x < n - 1 && passable[id(x + 1, y)] && h[id(x + 1, y)] > v + 1) {
            bool target = (x + 1 == x2 && y == y2);
            int lim = tmp[id(x + 1, y)];
            if ((target && lim >= v + 1) || (!target && lim > v + 1)) {
                qx[tail] = x + 1;
                qy[tail] = y;
                qd[tail++] = v + 1;
            }
        }
        if (y < n - 1 && passable[id(x, y + 1)] && h[id(x, y + 1)] > v + 1) {
            bool target = (x == x2 && y + 1 == y2);
            int lim = tmp[id(x, y + 1)];
            if ((target && lim >= v + 1) || (!target && lim > v + 1)) {
                qx[tail] = x;
                qy[tail] = y + 1;
                qd[tail++] = v + 1;
            }
        }
    }
    return h[id(x2, y2)];
}

int main() {
    cin >> n >> t;
    tmp.assign(n * n, t);
    passable.assign(n * n, 0);
    queue<pair<int, pair<int, int> > > q;
    char ch;
    int k = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> ch;
            tmp[id(i, j)] = t;
            if (ch == 'Z') {
                sx = i;
                sy = j;
                passable[id(i, j)] = 0;
            } else if (ch == 'Y') {
                passable[id(i, j)] = 0;
            } else {
                passable[id(i, j)] = 1;
            }
            add_edge(0, k++, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }

    k = n * n + 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cin >> ch;
            add_edge(k++, n * n * 2 + 1, (ch == 'Z' || ch == 'Y') ? 0 : ch - '0');
        }
    }

    q.push(make_pair(0, make_pair(sx, sy)));
    while (!q.empty()) {
        int v = q.front().first;
        int x = q.front().second.first;
        int y = q.front().second.second;
        q.pop();
        tmp[id(x, y)] = v;
        if (x > 0 && v + 1 < tmp[id(x - 1, y)] && passable[id(x - 1, y)])
            q.push(make_pair(v + 1, make_pair(x - 1, y)));
        if (y > 0 && v + 1 < tmp[id(x, y - 1)] && passable[id(x, y - 1)])
            q.push(make_pair(v + 1, make_pair(x, y - 1)));
        if (x < n - 1 && v + 1 < tmp[id(x + 1, y)] && passable[id(x + 1, y)])
            q.push(make_pair(v + 1, make_pair(x + 1, y)));
        if (y < n - 1 && v + 1 < tmp[id(x, y + 1)] && passable[id(x, y + 1)])
            q.push(make_pair(v + 1, make_pair(x, y + 1)));
    }

    k = 0;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            int k1 = n * n;
            ++k;
            for (int z = 0; z < n; ++z) {
                for (int w = 0; w < n; ++w) {
                    ++k1;
                    if (passable[id(i, j)] && passable[id(z, w)] && way(i, j, z, w) <= t)
                        add_edge(k, k1, INF);
                }
            }
        }
    }

    cout << max_flow();
    return 0;
}
